import{_ as t,o as a,c as r,a6 as i}from"./chunks/framework.CCKCzdWs.js";const o="/screenshots/vscode-failures.png",p=JSON.parse(`{"title":"Failures in the editor","description":"The latest CI run's failures in VS Code and the JetBrains IDEs: at the line that failed, with the heal as a quick fix, your local runs laid over them, followed through your edits, and as a tree in the failures view.","frontmatter":{"title":"Failures in the editor","description":"The latest CI run's failures in VS Code and the JetBrains IDEs: at the line that failed, with the heal as a quick fix, your local runs laid over them, followed through your edits, and as a tree in the failures view.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-failures.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-failures.html"}],["meta",{"property":"og:title","content":"Failures in the editor | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The latest CI run's failures in VS Code and the JetBrains IDEs: at the line that failed, with the heal as a quick fix, your local runs laid over them, followed through your edits, and as a tree in the failures view."}]]},"headers":[],"relativePath":"features/editor-failures.md","filePath":"features/editor-failures.md","lastUpdated":1793272175000}`),n={name:"features/editor-failures.md"};function s(l,e,h,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="failures-in-the-editor" tabindex="-1">Failures in the editor <a class="header-anchor" href="#failures-in-the-editor" aria-label="Permalink to &quot;Failures in the editor&quot;">​</a></h1><p>The <a href="./editors.html">editor extensions</a> show the failures of the latest CI run at the lines that failed, lay your local runs over them, and follow each failing line through your edits until a run covers its test again.</p><figure><img src="'+o+'" alt="VS Code: the failing tests marked in a spec, and the Failures view below"><figcaption>The failing tests in the spec, and the Failures view with the run you made since.</figcaption></figure><h2 id="ci-failures-in-the-problems-panel" tabindex="-1">CI failures in the Problems panel <a class="header-anchor" href="#ci-failures-in-the-problems-panel" aria-label="Permalink to &quot;CI failures in the Problems panel&quot;">​</a></h2><p>The failures of the latest complete <a href="/reference/test-metadata.html#run-origin">CI run</a> on the checked-out branch, else the default branch, are in the Problems panel, at the line that failed: the call in the error&#39;s stack when that file is in your workspace (often a page object), else the <code>test(…)</code> line, with the failure&#39;s headline. In the spec, the line a failing test failed at (the line that calls the page object, when it failed in one) is tinted darker, with the reason, <strong>Run this test</strong>, <strong>Screenshot</strong> and <strong>Trace</strong> above it.</p><p>On a failure, the quick fixes are:</p><ul><li><strong>Heal: use …</strong> makes the edit an <a href="/features/auto-heal.html">auto-heal pull request</a> would, when <a href="/features/locator-healing.html">locator healing</a> has a recommendation for the failing locator.</li><li><strong>Run this test</strong> runs the failing test; it comes first once you rewrote the line it failed at.</li><li><strong>Open the trace</strong> opens it in <code>npx playwright show-trace</code>.</li><li><strong>Reproduce in the desktop app</strong>, <strong>Find the breaking commit in the desktop app</strong> and <strong>Run Flake Lab on its untested suspects in the desktop app</strong>, for a test with an untested <a href="./flake-lab.html">flake suspect</a>, while the <a href="/features/desktop.html#jobs-from-your-editor">desktop app</a> runs; <strong>Share on …</strong> records the result.</li><li><strong>Apply the fix plan, then run its verification</strong>, when the failure&#39;s <a href="/features/failure-clusters.html">cluster</a> has a <a href="/features/fix-plans.html">fix plan</a> whose patch applies to your files: the edit is previewed, then the plan&#39;s verify command runs in a terminal.</li><li><strong>Copy context for agent</strong> copies the failure, its healing and fix plan.</li><li><strong>Open the failure in the dashboard</strong> opens the execution page, with its <a href="/features/evidence.html">evidence</a>.</li></ul><p>Hover for the error message, its call chain, the failure screenshot, and the tickets linked to its cluster or test. Without one, <strong>File an issue</strong> opens the cluster in the dashboard.</p><p>A failure of a run on the checked-out branch is an error; one from another branch, such as the default branch&#39;s while yours has no run yet, is a warning; one whose line you changed since the run is an information (a weak warning in a JetBrains IDE). The <code>piwi.failureSeverity</code> setting (<strong>Settings → Tools → Piwi → Runs</strong> in a JetBrains IDE) chooses <code>warning</code> or <code>information</code> in place of the error, or <code>off</code>: nothing in the Problems panel, while the failures view, the gutter and the lines above the tests still show the failures.</p><h2 id="your-local-runs" tabindex="-1">Your local runs <a class="header-anchor" href="#your-local-runs" aria-label="Permalink to &quot;Your local runs&quot;">​</a></h2><p>A later finished run on the branch, from the editor, <code>piwi run</code>, <code>npx playwright test</code> or the desktop app, overlays the latest CI run per test and Playwright project: a test it fixed leaves the Problems panel, its lens saying <em>fixed locally in run #124</em>; a test failing in it is an error labeled <em>local run #124</em>, or <em>your run #124</em> when this editor started it. The editor reads a run within a second of its end: <a href="./editor-runs.html#after-a-run">After a run</a>.</p><h2 id="failures-follow-your-edits" tabindex="-1">Failures follow your edits <a class="header-anchor" href="#failures-follow-your-edits" aria-label="Permalink to &quot;Failures follow your edits&quot;">​</a></h2><p>A run reports the line a test failed at in the files it ran. The editor reads those files as the run saw them and follows each failing line through your changes, saved or not:</p><ul><li>Add or remove lines above a failing line, and its error moves with it, in the Problems panel, the lines above the test and the failures view.</li><li>Rewrite the failing line, and the error turns into an information marker, <em>Edited since run #120: …</em>: the run said nothing about the new line. <strong>Run this test</strong> comes first among its quick fixes, and the reason above the line reads <em>✎ edited since run #120</em>. The test keeps its failing mark until a run says otherwise.</li><li>Delete the test, and its failure leaves the editor.</li></ul><p>The next run that covers the test says what is true: a failure there is an error again, and a pass takes it away.</p><p>For a CI run, the files as the run saw them are those of its commit (<code>git show</code>); for a local run, a run without a commit, or a commit your clone lacks, the files as saved when the editor first showed the failure.</p><h2 id="the-failures-view" tabindex="-1">The failures view <a class="header-anchor" href="#the-failures-view" aria-label="Permalink to &quot;The failures view&quot;">​</a></h2><p>The latest run&#39;s failures as a tree: the <strong>Failures</strong> view of the <strong>Piwi</strong> panel in VS Code, the Piwi tool window in a JetBrains IDE. Its first node is the run, <code>Run #120 · CI · feature/x · 3 failing · 1 fixed locally</code>, with its age, or the progress of the run you started (<code>running 4/9</code>). Under it:</p><ul><li><strong>Your runs since</strong> lists the runs laid over it, such as <code>#124 · your run · 2 min ago · 1 passed, 0 failed</code>; a click opens one in the dashboard.</li><li>The failures, grouped by spec (the default), by <a href="/features/failure-clusters.html">failure cluster</a>, by owner, or flat: <strong>Group by…</strong> in the view&#39;s title bar, the toggles of the tool window&#39;s toolbar. The choice is kept for the workspace, and each group counts its failures.</li><li>A failure shows its title, where it failed (<code>tests/login.spec.ts:42 · chromium · new</code>), and an icon for failing, edited since the run, or fixed locally, with the headline and its run (<code>your run #124</code>, <code>edited since run #120</code>).</li></ul><p>In a workspace with several Playwright configs, each config with a run, your runs or failures has a node of its own, named by its folder (<code>apps/admin</code>), with its project and counts beside it (<code>Admin · 2 failing</code>). Its run and failures are under it, as above, or its run alone when it fails nothing. Its row in VS Code, and its context menu in both editors, re-run that config&#39;s failing tests (<strong>Re-run the failing tests</strong>) and open its run in the dashboard; the context menu adds <strong>Compare with…</strong> for that config. With one config, the run is the first node.</p><p>Click a failure (double-click, Enter or <strong>Next Occurrence</strong> in a JetBrains IDE) to open its line. <strong>Run this test</strong>, <strong>Open the trace</strong> and <strong>Open in dashboard</strong> sit on its row in VS Code; the context menu adds <strong>Open the screenshot</strong>, <strong>Copy context for agent</strong>, and, on a CI failure while the <a href="/features/desktop.html#jobs-from-your-editor">desktop app</a> runs, <strong>Reproduce in the desktop app</strong> and <strong>Find the breaking commit in the desktop app</strong>. <strong>Heal</strong> stays a quick fix on the line.</p><p>The title bar, or the toolbar, holds Refresh, <strong>Re-run the failing tests</strong> (every config&#39;s), <strong>Open the run in the dashboard</strong> (the run the status bar shows), <strong>Compare with…</strong> (for the active file&#39;s config) and the grouping. In VS Code, <strong>Follow the active editor</strong> selects the first failure of the file you switch to, and the badge counts the failing tests, as the tool window&#39;s title does. The tree is read again when a run ends or an edit moves a failure.</p><h2 id="compare-with-another-run" tabindex="-1">Compare with another run <a class="header-anchor" href="#compare-with-another-run" aria-label="Permalink to &quot;Compare with another run&quot;">​</a></h2><p>By default, failures are read against the checked-out branch&#39;s latest complete run, else the default branch&#39;s. <strong>Piwi: Compare with…</strong> (<strong>Tools → Piwi → Compare With…</strong> in a JetBrains IDE, and the failures view&#39;s title bar) chooses another run to compare with: a branch&#39;s latest complete run, a run by its id, or <strong>My local runs only</strong>, your runs from this machine, the desktop app or an editor, without CI. Your runs since are laid over each. The status bar tooltip and the failures view name it (<code>Baseline: CI run #120 on feature/x</code>), ending with <code>(no run)</code> when it found none. The choice is kept on this machine, per Playwright config.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editors.html">Editor extensions</a>: what else the editor shows from your suite.</li><li><a href="./editor-runs.html">Runs from the editor</a>: run the failing tests again, and follow the run in the status bar.</li><li><a href="/features/locator-healing.html">Locator healing</a>: where the heal quick fix comes from.</li></ul>',26)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
